CREATE TABLE public.arborist_climber_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,business_id uuid NOT NULL REFERENCES public.businesses(id),role_name text NOT NULL DEFAULT 'arborist_only' CHECK(role_name='arborist_only'),active boolean NOT NULL DEFAULT true,granted_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id));
GRANT SELECT ON public.arborist_climber_access TO authenticated;
GRANT ALL ON public.arborist_climber_access TO service_role;
REVOKE ALL ON public.arborist_climber_access FROM anon;
ALTER TABLE public.arborist_climber_access ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_restricted_climber(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.arborist_climber_access WHERE user_id=_user_id) $$;
CREATE FUNCTION public.climber_can_work(_business_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.arborist_climber_access a JOIN public.businesses b ON b.id=a.business_id WHERE a.user_id=auth.uid() AND a.business_id=_business_id AND a.active AND upper(b.shortcode)='GCP') $$;
REVOKE ALL ON FUNCTION public.is_restricted_climber(uuid),public.climber_can_work(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_restricted_climber(uuid),public.climber_can_work(uuid) TO authenticated,service_role;
CREATE POLICY climber_access_read ON public.arborist_climber_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.arborist_can_review(business_id));
CREATE OR REPLACE FUNCTION public.arborist_can_access(_business_id uuid,_author_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT (auth.uid()=_author_id AND public.climber_can_work(_business_id)) OR (NOT public.is_restricted_climber(auth.uid()) AND public.has_business_access(auth.uid(),_business_id) AND EXISTS(SELECT 1 FROM public.businesses WHERE id=_business_id AND upper(shortcode)='GCP') AND (auth.uid()=_author_id OR public.arborist_can_review(_business_id))) $$;
CREATE FUNCTION public.climber_session() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('business_id',a.business_id,'active',a.active,'name',b.public_brand_name,'shortcode',b.shortcode) FROM public.arborist_climber_access a JOIN public.businesses b ON b.id=a.business_id WHERE a.user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.climber_session() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.climber_session() TO authenticated;
-- Every existing public table was verified RLS-enabled. Restrictive denial adds no staff grants.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename NOT IN ('arborist_climber_access','platform_arborist_quotes','platform_user_profiles') LOOP EXECUTE format('CREATE POLICY climber_deny_unrelated ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.is_restricted_climber(auth.uid())) WITH CHECK (NOT public.is_restricted_climber(auth.uid()))',t.tablename); END LOOP; END $$;
CREATE POLICY climber_profile_own ON public.platform_user_profiles AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.is_restricted_climber(auth.uid()) OR user_id=auth.uid()) WITH CHECK(NOT public.is_restricted_climber(auth.uid()) OR user_id=auth.uid());
CREATE POLICY climber_report_boundary ON public.platform_arborist_quotes AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.is_restricted_climber(auth.uid()) OR (author_id=auth.uid() AND public.climber_can_work(business_id))) WITH CHECK(NOT public.is_restricted_climber(auth.uid()) OR (author_id=auth.uid() AND public.climber_can_work(business_id) AND status IN ('draft','submitted')));
CREATE POLICY climber_storage_read ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.is_restricted_climber(auth.uid()) OR (bucket_id='arborist-quote-photos' AND public.arborist_photo_access(name,false)));
CREATE POLICY climber_storage_insert ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(NOT public.is_restricted_climber(auth.uid()) OR (bucket_id='arborist-quote-photos' AND public.arborist_photo_access(name,true)));
CREATE POLICY climber_storage_update ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(NOT public.is_restricted_climber(auth.uid())) WITH CHECK(NOT public.is_restricted_climber(auth.uid()));
CREATE POLICY climber_storage_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(NOT public.is_restricted_climber(auth.uid()));
CREATE FUNCTION public.climber_report_draft_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF public.is_restricted_climber(auth.uid()) AND OLD.status<>'draft' THEN RAISE EXCEPTION 'Submitted reports are read-only for climbers.' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.climber_report_draft_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER climber_report_draft_guard BEFORE UPDATE ON public.platform_arborist_quotes FOR EACH ROW EXECUTE FUNCTION public.climber_report_draft_guard();
ALTER TABLE public.platform_arborist_quotes ADD COLUMN pricing jsonb;
CREATE FUNCTION public.validate_report_pricing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r jsonb;k text;lo text;hi text; BEGIN
IF TG_OP='UPDATE' AND NEW.status='reviewed' AND NEW.pricing IS DISTINCT FROM OLD.pricing THEN RAISE EXCEPTION 'Save pricing as a draft before review'; END IF;
IF NEW.pricing IS NULL THEN RETURN NEW; END IF;
IF jsonb_typeof(NEW.pricing) IS DISTINCT FROM 'object' OR (NEW.pricing->>'basis' IN ('per_tree','whole_job')) IS NOT TRUE OR (NEW.pricing->>'disposalBasis' IN ('additional','complete')) IS NOT TRUE OR jsonb_typeof(NEW.pricing->'roadsideConditions') IS DISTINCT FROM 'string' OR length(NEW.pricing->>'roadsideConditions')>2000 THEN RAISE EXCEPTION 'Invalid structured report pricing'; END IF;
FOREACH k IN ARRAY ARRAY['wholeJob','haulAway','roadside'] LOOP r:=NEW.pricing->k;
IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR (r->>'priceType' IN ('fixed','range','unsure')) IS NOT TRUE OR jsonb_typeof(r->'priceMin') IS DISTINCT FROM 'string' OR jsonb_typeof(r->'priceMax') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid price recommendation'; END IF;
lo:=btrim(r->>'priceMin');hi:=btrim(r->>'priceMax');
IF (lo<>'' AND lo !~ '^\d{1,7}(\.\d{1,2})?$') OR (hi<>'' AND hi !~ '^\d{1,7}(\.\d{1,2})?$') THEN RAISE EXCEPTION 'Invalid price recommendation'; END IF;
IF r->>'priceType'='range' AND lo<>'' AND hi<>'' AND hi::numeric<lo::numeric THEN RAISE EXCEPTION 'Reversed price range'; END IF;
END LOOP; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_report_pricing() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_report_pricing BEFORE INSERT OR UPDATE ON public.platform_arborist_quotes FOR EACH ROW EXECUTE FUNCTION public.validate_report_pricing();
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename='platform_arborist_quotes') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.platform_arborist_quotes; END IF; END $$;
CREATE FUNCTION public.validate_climber_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
IF TG_OP='UPDATE' AND (NEW.user_id<>OLD.user_id OR NEW.business_id<>OLD.business_id) THEN RAISE EXCEPTION 'Climber account identity cannot change'; END IF;
IF NOT public.arborist_user_can_review(NEW.granted_by,NEW.business_id) THEN RAISE EXCEPTION 'Only GCP office staff can provision climbers'; END IF;
IF EXISTS(SELECT 1 FROM public.user_business_access WHERE user_id=NEW.user_id AND active_status='active') OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.user_id) OR EXISTS(SELECT 1 FROM public.workspaces WHERE owner_user_id=NEW.user_id) THEN RAISE EXCEPTION 'This account already has staff access. Use a separate climber-only account; existing staff access is unchanged.'; END IF;
IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=NEW.user_id) THEN RAISE EXCEPTION 'Account not found'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_climber_access() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_climber_access BEFORE INSERT OR UPDATE ON public.arborist_climber_access FOR EACH ROW EXECUTE FUNCTION public.validate_climber_access();
CREATE FUNCTION public.deny_climber_role_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE target uuid; BEGIN target:=CASE WHEN TG_TABLE_NAME='workspaces' THEN (to_jsonb(NEW)->>'owner_user_id')::uuid ELSE (to_jsonb(NEW)->>'user_id')::uuid END; PERFORM pg_advisory_xact_lock(hashtextextended(target::text,0)); IF public.is_restricted_climber(target) THEN RAISE EXCEPTION 'Arborist-only accounts cannot receive other roles' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.deny_climber_role_escalation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER deny_climber_staff_access BEFORE INSERT OR UPDATE ON public.user_business_access FOR EACH ROW EXECUTE FUNCTION public.deny_climber_role_escalation();
CREATE TRIGGER deny_climber_global_role BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.deny_climber_role_escalation();
CREATE TRIGGER deny_climber_ownership BEFORE INSERT OR UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.deny_climber_role_escalation();
CREATE OR REPLACE FUNCTION public.arborist_link_save(_token_hash text,_expected_version integer,_fields jsonb,_status text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE report public.platform_arborist_quotes;saved public.platform_arborist_quotes;k text; BEGIN
report:=public.arborist_link_lock(_token_hash); IF report.version IS DISTINCT FROM _expected_version THEN RAISE EXCEPTION 'link_stale'; END IF; IF _status NOT IN ('draft','submitted') THEN RAISE EXCEPTION 'link_bad_status'; END IF; IF jsonb_typeof(_fields) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'link_bad_fields'; END IF;
FOREACH k IN ARRAY ARRAY['customer_name','property_address','visit_date','arborist_name','general_notes'] LOOP IF jsonb_typeof(_fields->k) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'link_bad_fields'; END IF; END LOOP;
IF jsonb_typeof(_fields->'trees') IS DISTINCT FROM 'array' OR (_fields->>'visit_date') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'link_bad_fields'; END IF;
PERFORM set_config('app.arborist_link_report',report.id::text,true);
UPDATE public.platform_arborist_quotes SET customer_name=btrim(_fields->>'customer_name'),property_address=btrim(_fields->>'property_address'),visit_date=(_fields->>'visit_date')::date,arborist_name=btrim(_fields->>'arborist_name'),general_notes=btrim(_fields->>'general_notes'),trees=_fields->'trees',pricing=CASE WHEN _fields ? 'pricing' THEN _fields->'pricing' ELSE report.pricing END,status=_status WHERE id=report.id RETURNING * INTO saved;
PERFORM set_config('app.arborist_link_report','',true); RETURN to_jsonb(saved); END $$;
REVOKE ALL ON FUNCTION public.arborist_link_save(text,integer,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.arborist_link_save(text,integer,jsonb,text) TO service_role;
CREATE OR REPLACE FUNCTION public.arborist_photo_access(_name text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE parts text[];report public.platform_arborist_quotes; BEGIN
parts:=string_to_array(_name,'/');IF array_length(parts,1)<>5 THEN RETURN false; END IF; IF parts[5] !~ '^[0-9a-f-]{36}\.jpg$' THEN RETURN false; END IF;
SELECT * INTO report FROM public.platform_arborist_quotes WHERE id=parts[3]::uuid AND business_id=parts[1]::uuid AND author_id=parts[2]::uuid;
IF NOT FOUND OR NOT public.arborist_can_access(report.business_id,report.author_id) THEN RETURN false; END IF;
IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(report.trees) t WHERE t->>'id'=parts[4]) THEN RETURN false; END IF;
IF _write AND public.is_restricted_climber(auth.uid()) THEN RETURN report.status='draft'; END IF;
RETURN NOT _write OR report.status<>'reviewed' OR public.arborist_can_review(report.business_id);
EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
-- Reviewed PL/pgSQL signatures only; keep original bodies, languages and staff semantics.
DO $$ DECLARE signature text;definition text;body text;guarded text; BEGIN
FOREACH signature IN ARRAY ARRAY['backfill_jobber_to_platform()','close_clock_session_with_reason(uuid,timestamptz,text)','create_business_notification(uuid,text,text,text,text,text,text,text,uuid)','create_yearly_auto_job(uuid)','delete_email(text,bigint)','email_queue_dispatch()','enqueue_email(text,jsonb)','finance_import_bank_csv(uuid,text,text,jsonb)','flag_stale_clock_sessions(uuid)','generate_next_number(uuid,text)','get_audit_logs_filtered(uuid,uuid,text,text,text,timestamptz,timestamptz,integer,integer)','get_email_send_log_filtered(text,text,timestamptz,timestamptz,integer,integer)','get_yearly_trimming_count(uuid)','get_yearly_trimming_for_job(uuid,uuid)','get_yearly_trimming_roster(uuid)','invoice_accepted_quote(uuid)','move_to_dlq(text,text,bigint,jsonb)','process_yearly_autoschedule()','read_email_batch(text,integer,integer)','run_jobber_auto_sync()','set_yearly_trimming_for_job(uuid,uuid,boolean,uuid)','sms_upsert_conversation(uuid,text,text,text,text,uuid,boolean)','website_analytics_summary(uuid,timestamptz,timestamptz)'] LOOP
SELECT pg_get_functiondef(p.oid),p.prosrc INTO definition,body FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=('public.'||signature)::regprocedure AND l.lanname='plpgsql';
IF definition IS NULL OR body !~ E'\nBEGIN\n' THEN RAISE EXCEPTION 'Reviewed function entry point changed: %',signature; END IF;
guarded:=replace(body,E'\nBEGIN\n',E'\nBEGIN\n IF public.is_restricted_climber(auth.uid()) THEN RAISE EXCEPTION ''Arborist-only account: unrelated API denied.'' USING ERRCODE=''42501''; END IF;\n');
IF length(guarded)-length(body)<>length(E' IF public.is_restricted_climber(auth.uid()) THEN RAISE EXCEPTION ''Arborist-only account: unrelated API denied.'' USING ERRCODE=''42501''; END IF;\n') THEN RAISE EXCEPTION 'Ambiguous function entry point: %',signature; END IF;
EXECUTE replace(definition,body,guarded);END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.find_duplicate_customers(_business_id uuid,_phone text DEFAULT NULL,_email text DEFAULT NULL) RETURNS SETOF public.platform_customers LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT * FROM public.platform_customers WHERE NOT public.is_restricted_climber(auth.uid()) AND business_id=_business_id AND ((_phone IS NOT NULL AND phone=_phone) OR (_email IS NOT NULL AND email=_email)) ORDER BY created_at DESC LIMIT 5 $$;
CREATE OR REPLACE FUNCTION public.find_duplicate_leads(_business_id uuid,_phone text DEFAULT NULL,_email text DEFAULT NULL) RETURNS SETOF public.platform_leads LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT * FROM public.platform_leads WHERE NOT public.is_restricted_climber(auth.uid()) AND business_id=_business_id AND lead_status NOT IN ('lost') AND ((_phone IS NOT NULL AND inquiry_phone=_phone) OR (_email IS NOT NULL AND inquiry_email=_email)) ORDER BY created_at DESC LIMIT 5 $$;
CREATE OR REPLACE FUNCTION public.get_business_recipient_user_ids(_business_id uuid) RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT user_id FROM (SELECT DISTINCT user_id FROM public.user_business_access WHERE business_id=_business_id AND active_status='active' UNION SELECT DISTINCT w.owner_user_id FROM public.workspaces w JOIN public.businesses b ON b.workspace_id=w.id WHERE b.id=_business_id AND w.owner_user_id IS NOT NULL) recipients WHERE NOT public.is_restricted_climber(auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.get_user_business_ids(_user_id uuid) RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT business_id FROM public.user_business_access WHERE NOT public.is_restricted_climber(auth.uid()) AND user_id=_user_id AND active_status='active' $$;